const EUC_JP_SEQUENCE_ENCODE: &[(&str, u32, u8)] = &[];

pub(crate) fn is_charmap_encoding(name: &str) -> bool {
    table(name).is_some()
}

pub(crate) fn decode_charmap_strict(name: &str, payload: &[u8]) -> Option<String> {
    let table = table(name)?;
    let mut decoded = String::with_capacity(payload.len());
    for &byte in payload {
        let value = table[byte as usize];
        if value == INVALID {
            return None;
        }
        decoded.push(char::from_u32(value)?);
    }
    Some(decoded)
}

pub(crate) fn encode_charmap_strict(name: &str, text: &str) -> Option<Vec<u8>> {
    let table = table(name)?;
    let mut encoded = Vec::with_capacity(text.len());
    for ch in text.chars() {
        let value = ch as u32;
        let Some(byte) = table.iter().position(|&candidate| candidate == value) else {
            return None;
        };
        encoded.push(byte as u8);
    }
    Some(encoded)
}

/// Python's `str.encode(name, "replace")` behavior for generated single-byte
/// charmaps: each scalar without a mapping becomes ASCII question mark.
pub(crate) fn encode_charmap_replace(name: &str, text: &str) -> Option<Vec<u8>> {
    let table = table(name)?;
    let mut encoded = Vec::with_capacity(text.len());
    for ch in text.chars() {
        let value = ch as u32;
        let byte = table
            .iter()
            .position(|&candidate| candidate == value)
            .map(|index| index as u8)
            .unwrap_or(b'?');
        encoded.push(byte);
    }
    Some(encoded)
}

pub(crate) fn decode_hz_strict(payload: &[u8]) -> Option<String> {
    let mut decoded = String::with_capacity(payload.len());
    let mut shifted = false;
    let mut index = 0usize;

    while index < payload.len() {
        let byte = payload[index];
        if shifted {
            if byte == b'~' {
                if payload.get(index + 1) == Some(&b'}') {
                    shifted = false;
                    index += 2;
                    continue;
                }
                return None;
            }

            let trail = *payload.get(index + 1)?;
            if !(0x21..=0x7e).contains(&byte) || !(0x21..=0x7e).contains(&trail) {
                return None;
            }
            decoded.push(hz_decode_pair(u16::from_be_bytes([byte, trail]))?);
            index += 2;
            continue;
        }

        if byte == b'~' {
            match payload.get(index + 1) {
                Some(b'{') => {
                    shifted = true;
                    index += 2;
                }
                Some(b'~') => {
                    decoded.push('~');
                    index += 2;
                }
                Some(b'\n') => index += 2,
                _ => return None,
            }
            continue;
        }

        if byte > 0x7f {
            return None;
        }
        decoded.push(byte as char);
        index += 1;
    }

    if shifted {
        None
    } else {
        Some(decoded)
    }
}

pub(crate) fn encode_hz_strict(text: &str) -> Option<Vec<u8>> {
    encode_hz(text, false)
}

pub(crate) fn encode_hz_replace(text: &str) -> Option<Vec<u8>> {
    encode_hz(text, true)
}

fn encode_hz(text: &str, replacement: bool) -> Option<Vec<u8>> {
    let mut encoded = Vec::with_capacity(text.len());
    let mut shifted = false;

    for character in text.chars() {
        if character.is_ascii() {
            if shifted {
                encoded.extend_from_slice(b"~}");
                shifted = false;
            }
            if character == '~' {
                encoded.extend_from_slice(b"~~");
            } else {
                encoded.push(character as u8);
            }
            continue;
        }

        let pair = match hz_encode_pair(character as u32) {
            Some(pair) => pair,
            None if replacement => {
                if shifted {
                    encoded.extend_from_slice(b"~}");
                    shifted = false;
                }
                encoded.push(b'?');
                continue;
            }
            None => return None,
        };
        if !shifted {
            encoded.extend_from_slice(b"~{");
            shifted = true;
        }
        encoded.extend_from_slice(&pair.to_be_bytes());
    }

    if shifted {
        encoded.extend_from_slice(b"~}");
    }
    Some(encoded)
}

fn hz_decode_pair(pair: u16) -> Option<char> {
    let index = HZ_DECODE_PAIRS
        .binary_search_by_key(&pair, |(candidate, _)| *candidate)
        .ok()?;
    char::from_u32(HZ_DECODE_PAIRS[index].1)
}

fn hz_encode_pair(scalar: u32) -> Option<u16> {
    let index = HZ_ENCODE_PAIRS
        .binary_search_by_key(&scalar, |(candidate, _)| *candidate)
        .ok()?;
    Some(HZ_ENCODE_PAIRS[index].1)
}

pub(crate) fn decode_euc_jis_2004_strict(payload: &[u8]) -> Option<String> {
    decode_euc_jis_strict(payload, EUC_JIS_2004_DECODE)
}

pub(crate) fn decode_euc_jisx0213_strict(payload: &[u8]) -> Option<String> {
    decode_euc_jis_strict(payload, EUC_JISX0213_DECODE)
}

pub(crate) fn decode_euc_jp_strict(payload: &[u8]) -> Option<String> {
    decode_euc_jis_strict(payload, EUC_JP_DECODE)
}

fn decode_euc_jis_strict(payload: &[u8], table: &'static [(u32, &'static str)]) -> Option<String> {
    let mut decoded = String::with_capacity(payload.len());
    let mut index = 0usize;

    while index < payload.len() {
        let byte = payload[index];
        if byte <= 0x7f {
            decoded.push(byte as char);
            index += 1;
            continue;
        }

        let (packed, width) = match byte {
            0x8e => {
                let trail = *payload.get(index + 1)?;
                if !(0xa1..=0xdf).contains(&trail) {
                    return None;
                }
                (u32::from_be_bytes([0, 0, byte, trail]), 2usize)
            }
            0x8f => {
                let lead = *payload.get(index + 1)?;
                let trail = *payload.get(index + 2)?;
                if !(0xa1..=0xfe).contains(&lead) || !(0xa1..=0xfe).contains(&trail) {
                    return None;
                }
                (u32::from_be_bytes([0, byte, lead, trail]), 3usize)
            }
            0xa1..=0xfe => {
                let trail = *payload.get(index + 1)?;
                if !(0xa1..=0xfe).contains(&trail) {
                    return None;
                }
                (u32::from_be_bytes([0, 0, byte, trail]), 2usize)
            }
            _ => return None,
        };
        decoded.push_str(euc_jis_decode_entry(table, packed)?);
        index += width;
    }

    Some(decoded)
}

pub(crate) fn encode_euc_jis_2004_strict(text: &str) -> Option<Vec<u8>> {
    encode_euc_jis(
        text,
        false,
        EUC_JIS_2004_ENCODE,
        EUC_JIS_2004_SEQUENCE_ENCODE,
    )
}

pub(crate) fn encode_euc_jis_2004_replace(text: &str) -> Option<Vec<u8>> {
    // Replacement-mode writes one question mark for every unmatched scalar
    // after attempting canonical two-scalar entries.
    encode_euc_jis(
        text,
        true,
        EUC_JIS_2004_ENCODE,
        EUC_JIS_2004_SEQUENCE_ENCODE,
    )
}

pub(crate) fn encode_euc_jisx0213_strict(text: &str) -> Option<Vec<u8>> {
    encode_euc_jis(
        text,
        false,
        EUC_JISX0213_ENCODE,
        EUC_JISX0213_SEQUENCE_ENCODE,
    )
}

pub(crate) fn encode_euc_jisx0213_replace(text: &str) -> Option<Vec<u8>> {
    encode_euc_jis(
        text,
        true,
        EUC_JISX0213_ENCODE,
        EUC_JISX0213_SEQUENCE_ENCODE,
    )
}

pub(crate) fn encode_euc_jp_strict(text: &str) -> Option<Vec<u8>> {
    encode_euc_jis(text, false, EUC_JP_ENCODE, EUC_JP_SEQUENCE_ENCODE)
}

pub(crate) fn encode_euc_jp_replace(text: &str) -> Option<Vec<u8>> {
    encode_euc_jis(text, true, EUC_JP_ENCODE, EUC_JP_SEQUENCE_ENCODE)
}

fn encode_euc_jis(
    text: &str,
    replacement: bool,
    scalar_table: &'static [(u32, u32, u8)],
    sequence_table: &'static [(&'static str, u32, u8)],
) -> Option<Vec<u8>> {
    let mut encoded = Vec::with_capacity(text.len());
    let mut remainder = text;

    while !remainder.is_empty() {
        if let Some((sequence, packed, width)) = sequence_table
            .iter()
            .find(|(sequence, _, _)| remainder.starts_with(*sequence))
        {
            append_euc_jis_bytes(&mut encoded, *packed, *width);
            remainder = &remainder[sequence.len()..];
            continue;
        }

        let character = remainder.chars().next()?;
        remainder = &remainder[character.len_utf8()..];
        if character.is_ascii() {
            encoded.push(character as u8);
            continue;
        }

        match euc_jis_encode_entry(scalar_table, character as u32) {
            Some((packed, width)) => append_euc_jis_bytes(&mut encoded, packed, width),
            None if replacement => encoded.push(b'?'),
            None => return None,
        }
    }

    Some(encoded)
}

fn euc_jis_decode_entry(
    table: &'static [(u32, &'static str)],
    packed: u32,
) -> Option<&'static str> {
    let index = table
        .binary_search_by_key(&packed, |(candidate, _)| *candidate)
        .ok()?;
    Some(table[index].1)
}

fn euc_jis_encode_entry(table: &'static [(u32, u32, u8)], scalar: u32) -> Option<(u32, u8)> {
    let index = table
        .binary_search_by_key(&scalar, |(candidate, _, _)| *candidate)
        .ok()?;
    let (_, packed, width) = table[index];
    Some((packed, width))
}

fn append_euc_jis_bytes(encoded: &mut Vec<u8>, packed: u32, width: u8) {
    let packed = packed.to_be_bytes();
    let start = packed.len() - usize::from(width);
    encoded.extend_from_slice(&packed[start..]);
}

pub(crate) fn decode_utf32_strict(
    name: &str,
    payload: &[u8],
    sig_payload: &[u8],
) -> Option<String> {
    let (little_endian, payload) = match name {
        "utf_32" => match sig_payload {
            [0xff, 0xfe, 0x00, 0x00] => (true, payload.get(4..)?),
            [0x00, 0x00, 0xfe, 0xff] => (false, payload.get(4..)?),
            _ => return None,
        },
        "utf_32_le" => (true, payload),
        "utf_32_be" => (false, payload),
        _ => return None,
    };

    if payload.len() % 4 != 0 {
        return None;
    }

    let mut decoded = String::with_capacity(payload.len() / 4);
    for chunk in payload.chunks_exact(4) {
        let value = if little_endian {
            u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]])
        } else {
            u32::from_be_bytes([chunk[0], chunk[1], chunk[2], chunk[3]])
        };
        decoded.push(char::from_u32(value)?);
    }
    Some(decoded)
}

pub(crate) fn encode_utf32_strict(name: &str, text: &str) -> Option<Vec<u8>> {
    let little_endian = match name {
        "utf_32" | "utf_32_le" => true,
        "utf_32_be" => false,
        _ => return None,
    };
    let mut encoded = Vec::with_capacity(text.len() * 4 + 4);
    if name == "utf_32" {
        encoded.extend_from_slice(&[0xff, 0xfe, 0x00, 0x00]);
    }
    for ch in text.chars() {
        let value = ch as u32;
        if little_endian {
            encoded.extend_from_slice(&value.to_le_bytes());
        } else {
            encoded.extend_from_slice(&value.to_be_bytes());
        }
    }
    Some(encoded)
}

pub(crate) fn decode_utf7_strict(payload: &[u8]) -> Option<String> {
    let mut decoded = String::with_capacity(payload.len());
    let mut index = 0usize;

    while index < payload.len() {
        let byte = payload[index];
        if byte > 0x7f {
            return None;
        }

        if byte != b'+' {
            decoded.push(byte as char);
            index += 1;
            continue;
        }

        if payload.get(index + 1) == Some(&b'-') {
            decoded.push('+');
            index += 2;
            continue;
        }

        let mut cursor = index + 1;
        let mut bits = 0u32;
        let mut bit_count = 0u8;
        let mut units = Vec::new();

        while let Some(&candidate) = payload.get(cursor) {
            let Some(value) = utf7_base64_value(candidate) else {
                break;
            };
            bits = (bits << 6) | value as u32;
            bit_count += 6;
            while bit_count >= 16 {
                bit_count -= 16;
                units.push(((bits >> bit_count) & 0xffff) as u16);
                bits &= (1 << bit_count) - 1;
            }
            cursor += 1;
        }

        if cursor == index + 1 || (bit_count > 0 && bits != 0) {
            return None;
        }

        let shifted = String::from_utf16(&units).ok()?;
        decoded.push_str(&shifted);

        if payload.get(cursor) == Some(&b'-') {
            cursor += 1;
        }
        index = cursor;
    }

    Some(decoded)
}

pub(crate) fn encode_utf7_strict(text: &str) -> Option<Vec<u8>> {
    let mut encoded = Vec::with_capacity(text.len());
    let mut shifted = Vec::new();

    for ch in text.chars() {
        if is_utf7_direct(ch) {
            flush_utf7_shifted(&mut shifted, &mut encoded)?;
            encoded.push(ch as u8);
        } else if ch == '+' {
            flush_utf7_shifted(&mut shifted, &mut encoded)?;
            encoded.extend_from_slice(b"+-");
        } else {
            let mut scratch = [0u16; 2];
            shifted.extend_from_slice(ch.encode_utf16(&mut scratch));
        }
    }

    flush_utf7_shifted(&mut shifted, &mut encoded)?;
    Some(encoded)
}

fn is_utf7_direct(ch: char) -> bool {
    matches!(
        ch,
        'A'..='Z'
            | 'a'..='z'
            | '0'..='9'
            | '\''
            | '('
            | ')'
            | ','
            | '-'
            | '.'
            | '/'
            | ':'
            | '?'
            | ' '
            | '\t'
            | '\r'
            | '\n'
    )
}

fn flush_utf7_shifted(shifted: &mut Vec<u16>, encoded: &mut Vec<u8>) -> Option<()> {
    if shifted.is_empty() {
        return Some(());
    }

    let mut bytes = Vec::with_capacity(shifted.len() * 2);
    for unit in shifted.drain(..) {
        bytes.extend_from_slice(&unit.to_be_bytes());
    }
    encoded.push(b'+');
    encode_base64_no_padding(&bytes, encoded);
    encoded.push(b'-');
    Some(())
}

fn encode_base64_no_padding(bytes: &[u8], encoded: &mut Vec<u8>) {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut index = 0usize;
    while index + 3 <= bytes.len() {
        let n = ((bytes[index] as u32) << 16)
            | ((bytes[index + 1] as u32) << 8)
            | bytes[index + 2] as u32;
        encoded.push(ALPHABET[((n >> 18) & 0x3f) as usize]);
        encoded.push(ALPHABET[((n >> 12) & 0x3f) as usize]);
        encoded.push(ALPHABET[((n >> 6) & 0x3f) as usize]);
        encoded.push(ALPHABET[(n & 0x3f) as usize]);
        index += 3;
    }

    match bytes.len() - index {
        1 => {
            let n = (bytes[index] as u32) << 16;
            encoded.push(ALPHABET[((n >> 18) & 0x3f) as usize]);
            encoded.push(ALPHABET[((n >> 12) & 0x3f) as usize]);
        }
        2 => {
            let n = ((bytes[index] as u32) << 16) | ((bytes[index + 1] as u32) << 8);
            encoded.push(ALPHABET[((n >> 18) & 0x3f) as usize]);
            encoded.push(ALPHABET[((n >> 12) & 0x3f) as usize]);
            encoded.push(ALPHABET[((n >> 6) & 0x3f) as usize]);
        }
        _ => {}
    }
}

fn utf7_base64_value(byte: u8) -> Option<u8> {
    match byte {
        b'A'..=b'Z' => Some(byte - b'A'),
        b'a'..=b'z' => Some(byte - b'a' + 26),
        b'0'..=b'9' => Some(byte - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}
